SELECT jsonb_build_object('observed_at',statement_timestamp(),'gate',(SELECT to_jsonb(g) FROM marketing_private.collection_gate g),'migrations',(SELECT jsonb_agg(jsonb_build_object('version',version,'name',name,'statement_count',cardinality(statements),'statement_md5',md5(statements[1])) ORDER BY version) FROM supabase_migrations.schema_migrations WHERE name IN ('pazo_marketing_firstparty_attribution','pazo_marketing_retention_health')),'rows',jsonb_build_object('acquisition',(SELECT count(*) FROM marketing_private.acquisition),'landing',(SELECT count(*) FROM marketing_private.landing_daily),'minute_budget',(SELECT count(*) FROM marketing_private.landing_minute_budget)),'rls',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity) ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='marketing_private' AND c.relkind='r'),'role_access',(SELECT jsonb_agg(jsonb_build_object('role',r.role,'schema_usage',has_schema_privilege(r.role,'marketing_private','USAGE'),'any_table_privilege',(SELECT bool_or(has_table_privilege(r.role,c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='marketing_private' AND c.relkind='r'),'any_private_execute',(SELECT bool_or(has_function_privilege(r.role,p.oid,'EXECUTE')) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='marketing_private'))) FROM (VALUES('anon'),('authenticated'),('service_role')) r(role)),'marketing_cron_jobs',(SELECT count(*) FROM cron.job WHERE jobname='pazo-marketing-retention-v1'),'retention_runtime',(SELECT to_jsonb(r) FROM marketing_private.retention_runtime r),'financial_health',supporter_private.public_supporter_health(),'financial_functions_digest',(SELECT md5(string_agg(pg_get_functiondef(p.oid),E'\n' ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid))) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND (n.nspname='supporter_private' OR (n.nspname IN ('public','admin_private') AND p.proname LIKE '%paypal%')))) AS marketing_off_postflight;
